CREATE TABLE `system_config` (
	`id` int AUTO_INCREMENT NOT NULL,
	`configKey` varchar(64) NOT NULL,
	`configValue` text NOT NULL,
	`description` varchar(256),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `system_config_id` PRIMARY KEY(`id`),
	CONSTRAINT `system_config_configKey_unique` UNIQUE(`configKey`)
);

ALTER TABLE `bird_sightings` ADD `reviewStatus` enum('auto_approved','pending_review','approved','rejected') DEFAULT 'auto_approved' NOT NULL;
ALTER TABLE `bird_sightings` ADD `reviewedBy` int;
ALTER TABLE `bird_sightings` ADD `reviewedAt` timestamp;
ALTER TABLE `bird_sightings` ADD `reviewNote` text;

INSERT INTO `system_config` (`configKey`, `configValue`, `description`) VALUES
('confidenceThreshold', '0.75', '识别置信度阈值（0.0~1.0），低于此值的识别结果将进入待复核队列'),
('autoApproveEnabled', 'true', '是否启用自动通过（置信度≥阈值时自动标记为 auto_approved）')
ON DUPLICATE KEY UPDATE `configValue` = VALUES(`configValue`);

